const seed=[];let savedGroups=JSON.parse(localStorage.getItem('split-circle-groups')||'null');if(savedGroups?.some(group=>[1,2,3].includes(group.id))){localStorage.removeItem('split-circle-groups');savedGroups=null}let groups=savedGroups||seed,active=groups[0]||{id:null,name:'Create your first group',members:['You'],expenses:[]},method='equal';const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);function expenseShare(expense,person,group=active){if(expense.shares&&Object.prototype.hasOwnProperty.call(expense.shares,person))return Number(expense.shares[person]||0);return expense.method==='equal'?expense.total/group.members.length:Number(expense.shares?.[person]||0)}
function save(){localStorage.setItem('split-circle-groups',JSON.stringify(groups))}function render(){ $('#groups').innerHTML=groups.map(g=>'<div class="group-item '+(g===active?'active':'')+'" data-id="'+g.id+'"><div class="group-icon" style="background:'+(g===active?'#e5edc9':'#eee8dc')+'">'+g.icon+'</div><div><div class="group-name">'+g.name+'</div><div class="group-meta">'+g.members.length+' people · '+g.expenses.length+' splits</div></div></div>').join('');$('#groupTitle').textContent=active.name;$('#groupEyebrow').textContent=active.members.join(' · ');let owe=0,paid=0;active.expenses.forEach(e=>{if(e.method==='formula'&&!e.complete)return;let share=expenseShare(e,'You');if(e.payer==='You')paid+=e.total-share;else owe+=share});$('#owe').textContent=money(owe);$('#paid').textContent=money(paid);$('#expenses').innerHTML=active.expenses.length?active.expenses.map(e=>{let share=expenseShare(e,'You');return '<article class="expense"><div class="expense-ico">'+e.icon+'</div><div><div class="expense-title">'+e.title+(e.method==='formula'&&!e.complete?'<span class="split-status">Unfinished</span>':'')+'</div><div class="expense-sub">Paid by '+e.payer+' · '+e.date+'</div></div><div class="expense-amount">'+money(e.total)+(e.method==='formula'&&!e.complete?'<div class="expense-sub">answers needed</div>':e.payer!=='You'?'<div class="you-owe">you owe '+money(share)+'</div>':'<div class="expense-sub">you paid</div>')+'</div></article>'}).join(''):'<div class="empty">No purchases here yet. Add the first split.</div>'}render();
