  const joinParts=location.pathname.split('/');if(joinParts[1]!=='join'||!joinParts[2])return;const joinToken=joinParts[2],response=await fetch('/api/group-share-links/'+encodeURIComponent(joinToken));if(response.status===401)return;const data=await response.json();if(!response.ok){alert(data.error||'This share link is unavailable.');history.replaceState({},'', '/');return}if(data.isMember){history.replaceState({},'', '/');await loadRemoteGroups(data.group.id);return}
